def count_fully_disinfected_aliens(N: int, M: int, H: list) -> int:
    remaining_disinfectant = M
    fully_disinfected_aliens = 0

    for i in range(N):
        if remaining_disinfectant >= H[i]:
            remaining_disinfectant -= H[i]
            fully_disinfected_aliens += 1
        else:
            break

    return fully_disinfected_aliens
